private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (!bb.hasRemaining()) {
        return i;
    }
    int b1 = bb.get() & 0xFF;
    int codepoint;
    if ((b1 & 0x80) == 0) {
        // 1-byte ASCII
        codepoint = b1;
    } else if ((b1 & 0xE0) == 0xC0) {
        // 2-byte sequence
        if (!bb.hasRemaining()) {
            return i;
        }
        int b2 = bb.get() & 0xFF;
        codepoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
    } else if ((b1 & 0xF0) == 0xE0) {
        // 3-byte sequence
        if (bb.remaining() < 2) {
            return i;
        }
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        codepoint = ((b1 & 0x0F) << 12)
                  | ((b2 & 0x3F) << 6)
                  | (b3 & 0x3F);
    } else if ((b1 & 0xF8) == 0xF0) {
        // 4-byte sequence
        if (bb.remaining() < 3) {
            return i;
        }
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        int b4 = bb.get() & 0xFF;
        codepoint = ((b1 & 0x07) << 18)
                  | ((b2 & 0x3F) << 12)
                  | ((b3 & 0x3F) << 6)
                  | (b4 & 0x3F);
    } else {
        // Invalid UTF‑8 start byte – skip it
        return i;
    }

    if (codepoint <= 0xFFFF) {
        sb.append((char) codepoint);
        return i + 1;
    } else {
        // Surrogate pair
        codepoint -= 0x10000;
        char high = (char) ((codepoint >> 10) + 0xD800);
        char low = (char) ((codepoint & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
        return i + 2;
    }
}

