private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int requiredCapacity = pos + size; // 'pos' is the current write position / length of used bytes
    if (requiredCapacity <= buf.length) {
        return; // already enough space
    }
    int newCapacity = Math.max(requiredCapacity, buf.length * 2);
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, pos);
    buf = newBuf;
}

