public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Add all vertices to the target graph
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }
    // Create a simple bipartition of the vertices: first half vs second half
    List<V> vertices = new ArrayList<>(resultMap.values());
    int splitIndex = vertices.size() / 2;
    for (int i = 0; i < splitIndex; i++) {
        V left = vertices.get(i);
        for (int j = splitIndex; j < vertices.size(); j++) {
            V right = vertices.get(j);
            target.addEdge(left, right);
        }
    }
}

