static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    int monthDay = (int) (timeBucket % 10000L);
    int month = monthDay / 100;
    int day = monthDay % 100;
    int compressedDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100 + compressedDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int end = index + len;
    int byteCount = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            byteCount++;
        } else if (ch < 0x800) {
            byteCount += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            byteCount += 4;
            i++;
        } else {
            byteCount += 3;
        }
    }
    return byteCount;
}

