@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char primitive
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    // Null values are returned as null
    if (value == null) {
        return null;
    }
    // Directly return if already a Character
    if (value instanceof Character) {
        return value;
    }
    // Convert from String of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to Character");
        }
    }
    // Convert numeric types to char via int value
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    // Optional conversion from Boolean
    if (value instanceof Boolean) {
        return (Boolean) value ? '1' : '0';
    }
    // Unsupported conversion
    throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to Character");
}

