public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int length = str.length();
    StringBuilder sb = new StringBuilder(length);
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= length) {
                throw new IllegalArgumentException("Trailing backslash in string");
            }
            char next = str.charAt(i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= length) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    int codePoint = Integer.parseInt(hex, 16);
                    sb.append((char) codePoint);
                    i += 4;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i;
                        int val = next - '0';
                        if (j + 1 < length) {
                            char c2 = str.charAt(j + 1);
                            if (c2 >= '0' && c2 <= '7') {
                                val = val * 8 + (c2 - '0');
                                j++;
                                if (j + 1 < length) {
                                    char c3 = str.charAt(j + 1);
                                    if (c3 >= '0' && c3 <= '7') {
                                        val = val * 8 + (c3 - '0');
                                        j++;
                                    }
                                }
                            }
                        }
                        sb.append((char) val);
                        i = j;
                    } else {
                        sb.append(next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

