protected int removeUnusedNodes() {
    int removed = 0;
    if (root == null) {
        return 0;
    }
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        Iterator<Category> it = current.getChildren().iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

