final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int oldPos = classFileBuffer.position();
    int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    if (entryOffset < 0) {
        throw new IllegalArgumentException("Invalid constant pool index");
    }
    classFileBuffer.position(entryOffset);
    byte tag = classFileBuffer.get();
    if (tag != /* CONSTANT_Utf8 tag value */ 1) {
        throw new IllegalArgumentException("Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    int utfLen = classFileBuffer.getShort() & 0xFFFF;
    byte[] utfBytes = new byte[utfLen];
    classFileBuffer.get(utfBytes);
    classFileBuffer.position(oldPos);
    String utf = new String(utfBytes, java.nio.charset.StandardCharsets.UTF_8);
    if (charBuffer != null && charBuffer.length >= utfLen) {
        utf.getChars(0, utfLen, charBuffer, 0);
    }
    return utf;
}

