private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        return;
    }
    if (minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> target = (bucketsByLabel.size() > 0) ? bucketsByLabel.get(0) : null;
    if (target == null) {
        target = new HashSet<>();
        if (bucketsByLabel.size() == 0) {
            bucketsByLabel.add(target);
        } else {
            bucketsByLabel.set(0, target);
        }
    }
    for (Integer vertex : source) {
        target.add(vertex);
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    source.clear();
}

