public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assumes a field 'name' containing the full string to abbreviate
    if (name == null) {
        return;
    }
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    String rest = name.substring(nameStart);
    String[] parts = rest.split("\\.");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(part.charAt(0)).append('.');
        }
    }
    int len = buf.length();
    if (len > 0 && buf.charAt(len - 1) == '.') {
        buf.setLength(len - 1);
    }
}

