private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A subgraph with 0 or 1 vertices is vacuously a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Iterate over all unordered pairs of vertices
    for (V v : vertices) {
        for (V u : vertices) {
            if (v.equals(u)) {
                continue;
            }
            // For undirected graphs, containsEdge(v, u) should be true
            if (!graph.containsEdge(v, u)) {
                return false;
            }
        }
    }
    return true;
}

