private void pop(final String descriptor){
    int pos = 0;
    if (descriptor.charAt(0) == '('){
        pos = 1;
        while (descriptor.charAt(pos) != ')'){
            // parse a type
            if (descriptor.charAt(pos) == '['){
                while (descriptor.charAt(pos) == '[') pos++;
                if (descriptor.charAt(pos) == 'L'){
                    int sem = descriptor.indexOf(';', pos);
                    pos = sem + 1;
                } else {
                    pos++; // primitive type
                }
            } else if (descriptor.charAt(pos) == 'L'){
                int sem = descriptor.indexOf(';', pos);
                pos = sem + 1;
            } else {
                pos++; // primitive type
            }
            frameStack.pop();
        }
    } else {
        // single type descriptor
        if (descriptor.charAt(0) == '['){
            while (descriptor.charAt(pos) == '[') pos++;
            if (descriptor.charAt(pos) == 'L'){
                int sem = descriptor.indexOf(';', pos);
                pos = sem + 1;
            } else {
                pos++;
            }
        } else if (descriptor.charAt(0) == 'L'){
            int sem = descriptor.indexOf(';', 0);
            pos = sem + 1;
        } else {
            pos++;
        }
        frameStack.pop();
    }
}

