private void checkIfPackedField() throws IOException {
    int tag = peekTag(); // peek without consuming the tag
    if (tag == 0) {
        return;
    }
    int wireType = tag & 0x7;
    if (wireType == 2) { // LENGTH_DELIMITED
        packed = true;
        packedSize = readInt32(); // read length of packed data
        packedEnd = getPosition() + packedSize;
    } else {
        packed = false;
    }
}

