        // Grow the buffer (e.g., double its size or set to the needed size)
        int newCapacity = Math.max(this.buffer.length * 2, newLength);
        byte[] tmp = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, tmp, 0, this.length);
